    load(0);load(1);
    if(same(command,"users") || same(command,"groups")){unsigned k=same(command,"groups");for(size_t at=ID_HEADER;at<files[k].bytes;at+=id_u32(files[k].data+at)){const unsigned char *r=files[k].data+at;number(id_u64(r+8));say(" ");check(cb_write_all(&client,out,r+32,id_u32(r+(k?16:24))));if(!k){say(" gid=");number(id_u64(r+16));say(id_u32(r+4)?" active":" disabled");}else {say(" members:");for(size_t i=0;i<id_u32(r+20);++i){say(" ");number(id_u64(r+32+id_u32(r+16)+i*8));}}say("\n");}cb_exit(0);}
