    if(same(command,"useradd") || same(command,"groupadd")){unsigned k=same(command,"groupadd");size_t n=cb_length(name);if(!id_name((const unsigned char *)name,n) || n>UINT32_MAX-32 || named(k,name))fail(CB_BAD_REQUEST);uint64_t id=id_u64(files[k].data+40);if(id==UINT64_MAX)fail(CB_RESOURCE_FAILURE);unsigned char *r=alloc(32+n);for(size_t i=0;i<32;++i)r[i]=0;id_put32(r,32+n);id_put64(r+8,id);if(!k){const unsigned char *g=named(1,value?value:"users");if(!g)fail(CB_NOT_FOUND);id_put32(r+4,1);id_put64(r+16,id_u64(g+8));id_put32(r+24,n);}else id_put32(r+16,n);cb_copy(r+32,name,n);replace(k,NULL,r,32+n);release(r);id_put64(files[k].data+40,id+1);commit(UINT64_MAX);cb_exit(0);}
    if(same(command,"join") || same(command,"leave")){const unsigned char *u=named(0,name),*g=value?named(1,value):NULL;if(!u || !g)fail(CB_NOT_FOUND);member(id_u64(g+8),id_u64(u+8),same(command,"join"));commit(UINT64_MAX);cb_exit(0);}
    unsigned k=same(command,"groupdel") || same(command,"grouprename");const unsigned char *old=named(k,name);if(!old)fail(CB_NOT_FOUND);uint64_t deleted=UINT64_MAX;
    if(same(command,"userdel") || same(command,"groupdel")){uint64_t id=id_u64(old+8);replace(k,old,NULL,0);if(!k){deleted=id;for(size_t at=ID_HEADER;at<files[1].bytes;){uint64_t gid=id_u64(files[1].data+at+8);member(gid,id,0);at+=id_u32(id_find(&files[1],gid));}}}
    else if(same(command,"enable") || same(command,"disable")){id_put32((unsigned char *)old+4,same(command,"enable"));}
    else if(same(command,"primary")){const unsigned char *g=value?named(1,value):NULL;if(!g)fail(CB_NOT_FOUND);id_put64((unsigned char *)old+16,id_u64(g+8));}
    else if(same(command,"rename") || same(command,"grouprename")){if(!value || !id_name((const unsigned char *)value,cb_length(value)) || named(k,value))fail(CB_BAD_REQUEST);size_t n=cb_length(value),was=id_u32(old+(k?16:24)),tail=id_u32(old)-32-was;unsigned char *r=alloc(32+n+tail);cb_copy(r,old,32);id_put32(r,32+n+tail);id_put32(r+(k?16:24),n);cb_copy(r+32,value,n);cb_copy(r+32+n,old+32+was,tail);replace(k,old,r,32+n+tail);release(r);}
